import{_ as o,o as e,c as t,a3 as r}from"./chunks/framework.BveOjhN0.js";const g=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍"},"headers":[],"relativePath":"zh/00.docs/045.cross-language/010.introduction.md","filePath":"zh/00.docs/045.cross-language/010.introduction.md","lastUpdated":1782621505000}'),c={name:"zh/00.docs/045.cross-language/010.introduction.md"};function d(n,a,s,i,p,l){return e(),t("div",null,[...a[0]||(a[0]=[r('<p><code>electron</code>技术本身提供 <code>node.js</code>、<code>c/c++</code>(.node扩展) 语言支持。但为了拓展不同技术栈的开发者都能使用electron技术， 框架提供了<code>cross模块</code>，来创建其它语言的服务（子）进程。同时提供统一的API来管理这些进程。</p><p>理论上该模块可以支持任何语言创建的服务程序。目前提供 <code>go</code>、<code>java</code>的demo，可供参考。</p><p>由于<code>go</code>语言的契合度相对较高（跨平台、性能、包体大小、易用程度等），因此框架对go语言提供了深度集成，并提供更多支持。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><h4 id="go" tabindex="-1">go <a class="header-anchor" href="#go" aria-label="Permalink to &quot;go&quot;">​</a></h4><p>创建go服务</p><p>请查看文档：<a href="/pages/b16aa7/"><strong>go</strong></a></p><h4 id="java" tabindex="-1">java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;java&quot;">​</a></h4><p>创建java服务</p><p>请查看文档：<a href="/pages/368cc3/"><strong>java</strong></a></p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>更多功能，以api的方式提供。</p><p>请查看文档：<a href="/pages/74c87a/"><strong>cross API</strong></a></p>',13)])])}const _=o(c,[["render",d]]);export{g as __pageData,_ as default};
